import asyncio import logging from typing import Optional, Dict, Any
import asyncpg from fastapi import APIRouter, Depends, HTTPException, Query, Body from fastapi.responses import JSONResponse from sqlalchemy.ext.asyncio import AsyncSession
from api.dependencies import get_current_user, get_db_pool_optional from api.models.awakening import ( AwakeningActionRequest, AwakeningHistory, AwakeningStatusResponse ) from api.models.user import UserProfile as User from app.infrastructure.database.session import get_async_session from app.application.services.awakening_service import AwakeningService from app.application.services.progression_service import ProgressionService from core.config import settings
logger = logging.getLogger(__name__)
router = APIRouter()
async def get_awakening_service( session: AsyncSession = Depends(get_async_session), ) -> AwakeningService: """Get the awakening service with database session.""" progression_service = ProgressionService(session) return AwakeningService(session, progression_service)
@router.post("/action", response_model=Dict[str, Any]) async def process_awakening_action( request: AwakeningActionRequest, current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), ): """Create a new daily awakening session with personalized quests.""" try: logger.info( f"Processing awakening action for user {current_user.user_id} with readiness {request.readiness_level}" )
# Create new daily session session = await service.create_daily_session( current_user.user_id, request.readiness_level )
# Return session details return { "session_id": session.id, "session_date": session.session_date.isoformat(), "tier_level": session.tier_level, "status": session.status, "quest_count": len(session.quests), "quests": [ { "id": q.id, "type": q.quest_type, "target_movement": q.target_movement, "target_reps": q.target_reps, "target_time": q.target_time, "target_distance": q.target_distance, "difficulty": q.difficulty_level, "status": q.status } for q in session.quests ] } except Exception as e: logger.exception( f"Error processing awakening action for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=400, detail=str(e))
@router.post("/complete_quest/{quest_id}", response_model=Dict[str, Any]) async def complete_quest( quest_id: int, progress_data: Dict[str, Any] = Body(...), current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), ): """Complete a specific awakening quest with progress data.""" try: logger.info( f"Completing quest {quest_id} for user {current_user.user_id}" ) result = await service.complete_quest( current_user.user_id, quest_id, progress_data ) return result except Exception as e: logger.exception( f"Error completing quest {quest_id} for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=400, detail=str(e))
@router.get("/daily_briefing", response_model=Dict[str, Any]) async def get_daily_briefing( current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), ): """Get the daily awakening briefing with current progress.""" try: logger.info(f"Fetching daily briefing for user {current_user.user_id}") progress = await service.get_awakening_progress(current_user.user_id)
if not progress.get("has_session"): return { "has_session": False, "message": "No awakening session found for today. Create one to begin your daily challenge.", "awakening_streak": progress.get("awakening_streak", 0), "can_create": True }
return progress except Exception as e: logger.exception( f"Error fetching daily briefing for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=500, detail=str(e))
@router.get("/history", response_model=Dict[str, Any]) async def get_awakening_history( current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), limit: int = Query(10, ge=1, le=100), ): """Get awakening session history for the user.""" try: logger.info(f"Fetching awakening history for user {current_user.user_id}")
# For now, return basic history structure # This would be expanded with actual historical data queries return { "user_id": current_user.user_id, "total_sessions": 0, "completed_sessions": 0, "current_streak": 0, "sessions": [] } except Exception as e: logger.exception( f"Error fetching awakening history for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=500, detail=str(e))
@router.get("/status", response_model=Dict[str, Any]) async def get_awakening_status( current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), include_quests: bool = Query(True), ): """Get current awakening status and progress.""" try: logger.info(f"Fetching awakening status for user {current_user.user_id}") progress = await service.get_awakening_progress(current_user.user_id) return progress except Exception as e: logger.exception( f"Error fetching awakening status for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=500, detail=str(e))
@router.post("/reset", response_model=Dict[str, Any]) async def reset_daily_session( current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), ): """Reset today's awakening session with reduced difficulty.""" try: logger.info(f"Resetting awakening session for user {current_user.user_id}") result = await service.reset_daily_session(current_user.user_id) return result except Exception as e: logger.exception( f"Error resetting session for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=400, detail=str(e))
@router.post("/recover", response_model=Dict[str, Any]) async def recover_session( current_user: User = Depends(get_current_user), service: AwakeningService = Depends(get_awakening_service), ): """Attempt to recover an awakening session (placeholder for future implementation).""" try: logger.info(f"Attempting to recover session for user {current_user.user_id}")
# For now, just return current status progress = await service.get_awakening_progress(current_user.user_id) return { "recovered": False, "message": "Session recovery not yet implemented", "current_status": progress } except Exception as e: logger.exception( f"Error recovering session for user {current_user.user_id}: {e}" ) raise HTTPException(status_code=500, detail=f"Recovery failed: {str(e)}")

from fastapi import APIRouter, Depends, HTTPException, Request from typing import Optional import httpx import jwt import os from datetime import datetime, timedelta import asyncpg
from api.models.auth import TokenResponse, DiscordOAuthRequest, LoginRequest, UserClaims from api.models.common import SuccessResponse from api.dependencies import get_db_pool_optional, is_development_mode
router = APIRouter()
# Discord OAuth2 configuration DISCORD_CLIENT_ID = os.getenv("DISCORD_CLIENT_ID") DISCORD_CLIENT_SECRET = os.getenv("DISCORD_CLIENT_SECRET") DISCORD_REDIRECT_URI = os.getenv("DISCORD_REDIRECT_URI", "http://localhost:8000/api/auth/discord/callback") JWT_SECRET_KEY = os.getenv("JWT_SECRET_KEY", "dev-secret-key-change-in-production") JWT_ALGORITHM = "HS256" JWT_EXPIRATION_HOURS = 24 * 7 # 7 days
def create_jwt_token(user_id: int, discord_id: str, username: str) -> str: """Create JWT token for user""" now = datetime.utcnow() exp = now + timedelta(hours=JWT_EXPIRATION_HOURS)
payload = { "user_id": user_id, "discord_id": discord_id, "username": username, "iat": int(now.timestamp()), "exp": int(exp.timestamp()) }
return jwt.encode(payload, JWT_SECRET_KEY, algorithm=JWT_ALGORITHM)
async def get_or_create_user(db_pool: Optional[asyncpg.Pool], discord_id: str, username: str) -> int: """Get existing user or create new one, returns user_id""" if not db_pool: # Development mode - return mock user_id return 1
async with db_pool.acquire() as conn: # Check if user exists user_id = await conn.fetchval( "SELECT user_id FROM users WHERE discord_id = $1", int(discord_id) )
if user_id: # Update username if changed await conn.execute( "UPDATE users SET username = $1 WHERE user_id = $2", username, user_id ) return user_id else: # Create new user user_id = await conn.fetchval( """ INSERT INTO users (discord_id, username, xp, level, xp_max) VALUES ($1, $2, 0, 1, 100) RETURNING user_id """, int(discord_id), username )
# Create user_json_data entry await conn.execute( "INSERT INTO user_json_data (user_id, data) VALUES ($1, $2)", user_id, "{}" )
return user_id
@router.post("/discord/callback", response_model=TokenResponse) async def discord_oauth_callback( request: DiscordOAuthRequest, db_pool: Optional[asyncpg.Pool] = Depends(get_db_pool_optional) ): """Handle Discord OAuth2 callback""" if is_development_mode(): raise HTTPException( status_code=501, detail="Discord OAuth2 not available in development mode. Use /auth/dev/login instead." )
if not DISCORD_CLIENT_ID or not DISCORD_CLIENT_SECRET: raise HTTPException( status_code=500, detail="Discord OAuth2 not configured" )
# Exchange authorization code for access token token_data = { "client_id": DISCORD_CLIENT_ID, "client_secret": DISCORD_CLIENT_SECRET, "grant_type": "authorization_code", "code": request.code, "redirect_uri": request.redirect_uri or DISCORD_REDIRECT_URI, }
headers = {"Content-Type": "application/x-www-form-urlencoded"}
async with httpx.AsyncClient() as client: # Get access token from Discord token_response = await client.post( "https://discord.com/api/oauth2/token", data=token_data, headers=headers )
if token_response.status_code != 200: raise HTTPException( status_code=400, detail="Failed to exchange code for token" )
token_info = token_response.json() access_token = token_info["access_token"]
# Get user info from Discord user_response = await client.get( "https://discord.com/api/users/@me", headers={"Authorization": f"Bearer {access_token}"} )
if user_response.status_code != 200: raise HTTPException( status_code=400, detail="Failed to get user info from Discord" )
user_info = user_response.json() discord_id = user_info["id"] username = user_info["username"]
# Get or create user in database user_id = await get_or_create_user(db_pool, discord_id, username)
# Create JWT token jwt_token = create_jwt_token(user_id, discord_id, username)
return TokenResponse( access_token=jwt_token, token_type="bearer", expires_in=JWT_EXPIRATION_HOURS * 3600, user_id=user_id, discord_id=discord_id, username=username )
@router.post("/dev/login", response_model=TokenResponse) async def dev_login( request: LoginRequest, db_pool: Optional[asyncpg.Pool] = Depends(get_db_pool_optional) ): """Development login endpoint (only available in dev mode)""" if not is_development_mode(): raise HTTPException( status_code=404, detail="Development login only available in development mode" )
# Get or create user user_id = await get_or_create_user(db_pool, request.discord_id, request.username)
# Create JWT token jwt_token = create_jwt_token(user_id, request.discord_id, request.username)
return TokenResponse( access_token=jwt_token, token_type="bearer", expires_in=JWT_EXPIRATION_HOURS * 3600, user_id=user_id, discord_id=request.discord_id, username=request.username )
@router.get("/me", response_model=UserClaims) async def get_current_user_info(request: Request): """Get current user info from JWT token""" auth_header = request.headers.get("Authorization") if not auth_header or not auth_header.startswith("Bearer "): raise HTTPException( status_code=401, detail="Missing or invalid authorization header" )
token = auth_header.split(" ")[1]
try: payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM]) return UserClaims(**payload) except jwt.ExpiredSignatureError: raise HTTPException(status_code=401, detail="Token has expired") except jwt.InvalidTokenError: raise HTTPException(status_code=401, detail="Invalid token")
@router.post("/logout", response_model=SuccessResponse) async def logout(): """Logout endpoint (client-side token removal)""" return SuccessResponse( success=True, message="Logged out successfully. Please remove the token from client storage." )
@router.get("/discord/url") async def get_discord_oauth_url(): """Get Discord OAuth2 authorization URL""" if is_development_mode(): return { "auth_url": None, "message": "Discord OAuth2 not available in development mode. Use /auth/dev/login instead.", "dev_mode": True }
if not DISCORD_CLIENT_ID: raise HTTPException( status_code=500, detail="Discord OAuth2 not configured" )
auth_url = ( f"https://discord.com/api/oauth2/authorize" f"?client_id={DISCORD_CLIENT_ID}" f"&redirect_uri={DISCORD_REDIRECT_URI}" f"&response_type=code" f"&scope=identify" )
return { "auth_url": auth_url, "redirect_uri": DISCORD_REDIRECT_URI, "dev_mode": False }

template: id: frontend-spec-template-v2 name: UI/UX Specification version: 2.0 output: format: markdown filename: docs/front-end-spec.md title: "{{project_name}} UI/UX Specification"
workflow: mode: interactive elicitation: advanced-elicitation
sections: - id: introduction title: Introduction instruction: | Review provided documents including Project Brief, PRD, and any user research to gather context. Focus on understanding user needs, pain points, and desired outcomes before beginning the specification.
Establish the document's purpose and scope. Keep the content below but ensure project name is properly substituted. content: | This document defines the user experience goals, information architecture, user flows, and visual design specifications for {{project_name}}'s user interface. It serves as the foundation for visual design and frontend development, ensuring a cohesive and user-centered experience. sections: - id: ux-goals-principles title: Overall UX Goals & Principles instruction: | Work with the user to establish and document the following. If not already defined, facilitate a discussion to determine:
1. Target User Personas - elicit details or confirm existing ones from PRD 2. Key Usability Goals - understand what success looks like for users 3. Core Design Principles - establish 3-5 guiding principles elicit: true sections: - id: user-personas title: Target User Personas template: "{{persona_descriptions}}" examples: - "**Power User:** Technical professionals who need advanced features and efficiency" - "**Casual User:** Occasional users who prioritize ease of use and clear guidance" - "**Administrator:** System managers who need control and oversight capabilities" - id: usability-goals title: Usability Goals template: "{{usability_goals}}" examples: - "Ease of learning: New users can complete core tasks within 5 minutes" - "Efficiency of use: Power users can complete frequent tasks with minimal clicks" - "Error prevention: Clear validation and confirmation for destructive actions" - "Memorability: Infrequent users can return without relearning" - id: design-principles title: Design Principles template: "{{design_principles}}" type: numbered-list examples: - "**Clarity over cleverness** - Prioritize clear communication over aesthetic innovation" - "**Progressive disclosure** - Show only what's needed, when it's needed" - "**Consistent patterns** - Use familiar UI patterns throughout the application" - "**Immediate feedback** - Every action should have a clear, immediate response" - "**Accessible by default** - Design for all users from the start" - id: changelog title: Change Log type: table columns: [Date, Version, Description, Author] instruction: Track document versions and changes
- id: information-architecture title: Information Architecture (IA) instruction: | Collaborate with the user to create a comprehensive information architecture:
1. Build a Site Map or Screen Inventory showing all major areas 2. Define the Navigation Structure (primary, secondary, breadcrumbs) 3. Use Mermaid diagrams for visual representation 4. Consider user mental models and expected groupings elicit: true sections: - id: sitemap title: Site Map / Screen Inventory type: mermaid mermaid_type: graph template: "{{sitemap_diagram}}" examples: - | graph TD A[Homepage] --> B[Dashboard] A --> C[Products] A --> D[Account] B --> B1[Analytics] B --> B2[Recent Activity] C --> C1[Browse] C --> C2[Search] C --> C3[Product Details] D --> D1[Profile] D --> D2[Settings] D --> D3[Billing] - id: navigation-structure title: Navigation Structure template: | **Primary Navigation:** {{primary_nav_description}}
**Secondary Navigation:** {{secondary_nav_description}}
**Breadcrumb Strategy:** {{breadcrumb_strategy}}
- id: user-flows title: User Flows instruction: | For each critical user task identified in the PRD:
1. Define the user's goal clearly 2. Map out all steps including decision points 3. Consider edge cases and error states 4. Use Mermaid flow diagrams for clarity 5. Link to external tools (Figma/Miro) if detailed flows exist there
Create subsections for each major flow. elicit: true repeatable: true sections: - id: flow title: "{{flow_name}}" template: | **User Goal:** {{flow_goal}}
**Entry Points:** {{entry_points}}
**Success Criteria:** {{success_criteria}} sections: - id: flow-diagram title: Flow Diagram type: mermaid mermaid_type: graph template: "{{flow_diagram}}" - id: edge-cases title: "Edge Cases & Error Handling:" type: bullet-list template: "- {{edge_case}}" - id: notes template: "**Notes:** {{flow_notes}}"
- id: wireframes-mockups title: Wireframes & Mockups instruction: | Clarify where detailed visual designs will be created (Figma, Sketch, etc.) and how to reference them. If low-fidelity wireframes are needed, offer to help conceptualize layouts for key screens. elicit: true sections: - id: design-files template: "**Primary Design Files:** {{design_tool_link}}" - id: key-screen-layouts title: Key Screen Layouts repeatable: true sections: - id: screen title: "{{screen_name}}" template: | **Purpose:** {{screen_purpose}}
**Key Elements:** - {{element_1}} - {{element_2}} - {{element_3}}
**Interaction Notes:** {{interaction_notes}}
**Design File Reference:** {{specific_frame_link}}
- id: component-library title: Component Library / Design System instruction: | Discuss whether to use an existing design system or create a new one. If creating new, identify foundational components and their key states. Note that detailed technical specs belong in front-end-architecture. elicit: true sections: - id: design-system-approach template: "**Design System Approach:** {{design_system_approach}}" - id: core-components title: Core Components repeatable: true sections: - id: component title: "{{component_name}}" template: | **Purpose:** {{component_purpose}}
**Variants:** {{component_variants}}
**States:** {{component_states}}
**Usage Guidelines:** {{usage_guidelines}}
- id: branding-style title: Branding & Style Guide instruction: Link to existing style guide or define key brand elements. Ensure consistency with company brand guidelines if they exist. elicit: true sections: - id: visual-identity title: Visual Identity template: "**Brand Guidelines:** {{brand_guidelines_link}}" - id: color-palette title: Color Palette type: table columns: ["Color Type", "Hex Code", "Usage"] rows: - ["Primary", "{{primary_color}}", "{{primary_usage}}"] - ["Secondary", "{{secondary_color}}", "{{secondary_usage}}"] - ["Accent", "{{accent_color}}", "{{accent_usage}}"] - ["Success", "{{success_color}}", "Positive feedback, confirmations"] - ["Warning", "{{warning_color}}", "Cautions, important notices"] - ["Error", "{{error_color}}", "Errors, destructive actions"] - ["Neutral", "{{neutral_colors}}", "Text, borders, backgrounds"] - id: typography title: Typography sections: - id: font-families title: Font Families template: | - **Primary:** {{primary_font}} - **Secondary:** {{secondary_font}} - **Monospace:** {{mono_font}} - id: type-scale title: Type Scale type: table columns: ["Element", "Size", "Weight", "Line Height"] rows: - ["H1", "{{h1_size}}", "{{h1_weight}}", "{{h1_line}}"] - ["H2", "{{h2_size}}", "{{h2_weight}}", "{{h2_line}}"] - ["H3", "{{h3_size}}", "{{h3_weight}}", "{{h3_line}}"] - ["Body", "{{body_size}}", "{{body_weight}}", "{{body_line}}"] - ["Small", "{{small_size}}", "{{small_weight}}", "{{small_line}}"] - id: iconography title: Iconography template: | **Icon Library:** {{icon_library}}
**Usage Guidelines:** {{icon_guidelines}} - id: spacing-layout title: Spacing & Layout template: | **Grid System:** {{grid_system}}
**Spacing Scale:** {{spacing_scale}}
- id: accessibility title: Accessibility Requirements instruction: Define specific accessibility requirements based on target compliance level and user needs. Be comprehensive but practical. elicit: true sections: - id: compliance-target title: Compliance Target template: "**Standard:** {{compliance_standard}}" - id: key-requirements title: Key Requirements template: | **Visual:** - Color contrast ratios: {{contrast_requirements}} - Focus indicators: {{focus_requirements}} - Text sizing: {{text_requirements}}
**Interaction:** - Keyboard navigation: {{keyboard_requirements}} - Screen reader support: {{screen_reader_requirements}} - Touch targets: {{touch_requirements}}
**Content:** - Alternative text: {{alt_text_requirements}} - Heading structure: {{heading_requirements}} - Form labels: {{form_requirements}} - id: testing-strategy title: Testing Strategy template: "{{accessibility_testing}}"
- id: responsiveness title: Responsiveness Strategy instruction: Define breakpoints and adaptation strategies for different device sizes. Consider both technical constraints and user contexts. elicit: true sections: - id: breakpoints title: Breakpoints type: table columns: ["Breakpoint", "Min Width", "Max Width", "Target Devices"] rows: - ["Mobile", "{{mobile_min}}", "{{mobile_max}}", "{{mobile_devices}}"] - ["Tablet", "{{tablet_min}}", "{{tablet_max}}", "{{tablet_devices}}"] - ["Desktop", "{{desktop_min}}", "{{desktop_max}}", "{{desktop_devices}}"] - ["Wide", "{{wide_min}}", "-", "{{wide_devices}}"] - id: adaptation-patterns title: Adaptation Patterns template: | **Layout Changes:** {{layout_adaptations}}
**Navigation Changes:** {{nav_adaptations}}
**Content Priority:** {{content_adaptations}}
**Interaction Changes:** {{interaction_adaptations}}
- id: animation title: Animation & Micro-interactions instruction: Define motion design principles and key interactions. Keep performance and accessibility in mind. elicit: true sections: - id: motion-principles title: Motion Principles template: "{{motion_principles}}" - id: key-animations title: Key Animations repeatable: true template: "- **{{animation_name}}:** {{animation_description}} (Duration: {{duration}}, Easing: {{easing}})"
- id: performance title: Performance Considerations instruction: Define performance goals and strategies that impact UX design decisions. sections: - id: performance-goals title: Performance Goals template: | - **Page Load:** {{load_time_goal}} - **Interaction Response:** {{interaction_goal}} - **Animation FPS:** {{animation_goal}} - id: design-strategies title: Design Strategies template: "{{performance_strategies}}"
- id: next-steps title: Next Steps instruction: | After completing the UI/UX specification:
1. Recommend review with stakeholders 2. Suggest creating/updating visual designs in design tool 3. Prepare for handoff to Design Architect for frontend architecture 4. Note any open questions or decisions needed sections: - id: immediate-actions title: Immediate Actions type: numbered-list template: "{{action}}" - id: design-handoff-checklist title: Design Handoff Checklist type: checklist items: - "All user flows documented" - "Component inventory complete" - "Accessibility requirements defined" - "Responsive strategy clear" - "Brand guidelines incorporated" - "Performance goals established"
- id: checklist-results title: Checklist Results instruction: If a UI/UX checklist exists, run it against this document and report results here.

template: id: brownfield-architecture-template-v2 name: Brownfield Enhancement Architecture version: 2.0 output: format: markdown filename: docs/architecture.md title: "{{project_name}} Brownfield Enhancement Architecture"
workflow: mode: interactive elicitation: advanced-elicitation
sections: - id: introduction title: Introduction instruction: | IMPORTANT - SCOPE AND ASSESSMENT REQUIRED:
This architecture document is for SIGNIFICANT enhancements to existing projects that require comprehensive architectural planning. Before proceeding:
1. **Verify Complexity**: Confirm this enhancement requires architectural planning. For simple additions, recommend: "For simpler changes that don't require architectural planning, consider using the brownfield-create-epic or brownfield-create-story task with the Product Owner instead."
2. **REQUIRED INPUTS**: - Completed brownfield-prd.md - Existing project technical documentation (from docs folder or user-provided) - Access to existing project structure (IDE or uploaded files)
3. **DEEP ANALYSIS MANDATE**: You MUST conduct thorough analysis of the existing codebase, architecture patterns, and technical constraints before making ANY architectural recommendations. Every suggestion must be based on actual project analysis, not assumptions.
4. **CONTINUOUS VALIDATION**: Throughout this process, explicitly validate your understanding with the user. For every architectural decision, confirm: "Based on my analysis of your existing system, I recommend [decision] because [evidence from actual project]. Does this align with your system's reality?"
If any required inputs are missing, request them before proceeding. elicit: true sections: - id: intro-content content: | This document outlines the architectural approach for enhancing {{project_name}} with {{enhancement_description}}. Its primary goal is to serve as the guiding architectural blueprint for AI-driven development of new features while ensuring seamless integration with the existing system.
**Relationship to Existing Architecture:** This document supplements existing project architecture by defining how new components will integrate with current systems. Where conflicts arise between new and existing patterns, this document provides guidance on maintaining consistency while implementing enhancements. - id: existing-project-analysis title: Existing Project Analysis instruction: | Analyze the existing project structure and architecture:
1. Review existing documentation in docs folder 2. Examine current technology stack and versions 3. Identify existing architectural patterns and conventions 4. Note current deployment and infrastructure setup 5. Document any constraints or limitations
CRITICAL: After your analysis, explicitly validate your findings: "Based on my analysis of your project, I've identified the following about your existing system: [key findings]. Please confirm these observations are accurate before I proceed with architectural recommendations." elicit: true sections: - id: current-state title: Current Project State template: | - **Primary Purpose:** {{existing_project_purpose}} - **Current Tech Stack:** {{existing_tech_summary}} - **Architecture Style:** {{existing_architecture_style}} - **Deployment Method:** {{existing_deployment_approach}} - id: available-docs title: Available Documentation type: bullet-list template: "- {{existing_docs_summary}}" - id: constraints title: Identified Constraints type: bullet-list template: "- {{constraint}}" - id: changelog title: Change Log type: table columns: [Change, Date, Version, Description, Author] instruction: Track document versions and changes
- id: enhancement-scope title: Enhancement Scope and Integration Strategy instruction: | Define how the enhancement will integrate with the existing system:
1. Review the brownfield PRD enhancement scope 2. Identify integration points with existing code 3. Define boundaries between new and existing functionality 4. Establish compatibility requirements
VALIDATION CHECKPOINT: Before presenting the integration strategy, confirm: "Based on my analysis, the integration approach I'm proposing takes into account [specific existing system characteristics]. These integration points and boundaries respect your current architecture patterns. Is this assessment accurate?" elicit: true sections: - id: enhancement-overview title: Enhancement Overview template: | **Enhancement Type:** {{enhancement_type}} **Scope:** {{enhancement_scope}} **Integration Impact:** {{integration_impact_level}} - id: integration-approach title: Integration Approach template: | **Code Integration Strategy:** {{code_integration_approach}} **Database Integration:** {{database_integration_approach}} **API Integration:** {{api_integration_approach}} **UI Integration:** {{ui_integration_approach}} - id: compatibility-requirements title: Compatibility Requirements template: | - **Existing API Compatibility:** {{api_compatibility}} - **Database Schema Compatibility:** {{db_compatibility}} - **UI/UX Consistency:** {{ui_compatibility}} - **Performance Impact:** {{performance_constraints}}
- id: tech-stack-alignment title: Tech Stack Alignment instruction: | Ensure new components align with existing technology choices:
1. Use existing technology stack as the foundation 2. Only introduce new technologies if absolutely necessary 3. Justify any new additions with clear rationale 4. Ensure version compatibility with existing dependencies elicit: true sections: - id: existing-stack title: Existing Technology Stack type: table columns: [Category, Current Technology, Version, Usage in Enhancement, Notes] instruction: Document the current stack that must be maintained or integrated with - id: new-tech-additions title: New Technology Additions condition: Enhancement requires new technologies type: table columns: [Technology, Version, Purpose, Rationale, Integration Method] instruction: Only include if new technologies are required for the enhancement
- id: data-models title: Data Models and Schema Changes instruction: | Define new data models and how they integrate with existing schema:
1. Identify new entities required for the enhancement 2. Define relationships with existing data models 3. Plan database schema changes (additions, modifications) 4. Ensure backward compatibility elicit: true sections: - id: new-models title: New Data Models repeatable: true sections: - id: model title: "{{model_name}}" template: | **Purpose:** {{model_purpose}} **Integration:** {{integration_with_existing}}
**Key Attributes:** - {{attribute_1}}: {{type_1}} - {{description_1}} - {{attribute_2}}: {{type_2}} - {{description_2}}
**Relationships:** - **With Existing:** {{existing_relationships}} - **With New:** {{new_relationships}} - id: schema-integration title: Schema Integration Strategy template: | **Database Changes Required:** - **New Tables:** {{new_tables_list}} - **Modified Tables:** {{modified_tables_list}} - **New Indexes:** {{new_indexes_list}} - **Migration Strategy:** {{migration_approach}}
**Backward Compatibility:** - {{compatibility_measure_1}} - {{compatibility_measure_2}}
- id: component-architecture title: Component Architecture instruction: | Define new components and their integration with existing architecture:
1. Identify new components required for the enhancement 2. Define interfaces with existing components 3. Establish clear boundaries and responsibilities 4. Plan integration points and data flow
MANDATORY VALIDATION: Before presenting component architecture, confirm: "The new components I'm proposing follow the existing architectural patterns I identified in your codebase: [specific patterns]. The integration interfaces respect your current component structure and communication patterns. Does this match your project's reality?" elicit: true sections: - id: new-components title: New Components repeatable: true sections: - id: component title: "{{component_name}}" template: | **Responsibility:** {{component_description}} **Integration Points:** {{integration_points}}
**Key Interfaces:** - {{interface_1}} - {{interface_2}}
**Dependencies:** - **Existing Components:** {{existing_dependencies}} - **New Components:** {{new_dependencies}}
**Technology Stack:** {{component_tech_details}} - id: interaction-diagram title: Component Interaction Diagram type: mermaid mermaid_type: graph instruction: Create Mermaid diagram showing how new components interact with existing ones
- id: api-design title: API Design and Integration condition: Enhancement requires API changes instruction: | Define new API endpoints and integration with existing APIs:
1. Plan new API endpoints required for the enhancement 2. Ensure consistency with existing API patterns 3. Define authentication and authorization integration 4. Plan versioning strategy if needed elicit: true sections: - id: api-strategy title: API Integration Strategy template: | **API Integration Strategy:** {{api_integration_strategy}} **Authentication:** {{auth_integration}} **Versioning:** {{versioning_approach}} - id: new-endpoints title: New API Endpoints repeatable: true sections: - id: endpoint title: "{{endpoint_name}}" template: | - **Method:** {{http_method}} - **Endpoint:** {{endpoint_path}} - **Purpose:** {{endpoint_purpose}} - **Integration:** {{integration_with_existing}} sections: - id: request title: Request type: code language: json template: "{{request_schema}}" - id: response title: Response type: code language: json template: "{{response_schema}}"
- id: external-api-integration title: External API Integration condition: Enhancement requires new external APIs instruction: Document new external API integrations required for the enhancement repeatable: true sections: - id: external-api title: "{{api_name}} API" template: | - **Purpose:** {{api_purpose}} - **Documentation:** {{api_docs_url}} - **Base URL:** {{api_base_url}} - **Authentication:** {{auth_method}} - **Integration Method:** {{integration_approach}}
**Key Endpoints Used:** - `{{method}} {{endpoint_path}}` - {{endpoint_purpose}}
**Error Handling:** {{error_handling_strategy}}
- id: source-tree-integration title: Source Tree Integration instruction: | Define how new code will integrate with existing project structure:
1. Follow existing project organization patterns 2. Identify where new files/folders will be placed 3. Ensure consistency with existing naming conventions 4. Plan for minimal disruption to existing structure elicit: true sections: - id: existing-structure title: Existing Project Structure type: code language: plaintext instruction: Document relevant parts of current structure template: "{{existing_structure_relevant_parts}}" - id: new-file-organization title: New File Organization type: code language: plaintext instruction: Show only new additions to existing structure template: | {{project-root}}/ ├── {{existing_structure_context}} │ ├── {{new_folder_1}}/ # {{purpose_1}} │ │ ├── {{new_file_1}} │ │ └── {{new_file_2}} │ ├── {{existing_folder}}/ # Existing folder with additions │ │ ├── {{existing_file}} # Existing file │ │ └── {{new_file_3}} # New addition │ └── {{new_folder_2}}/ # {{purpose_2}} - id: integration-guidelines title: Integration Guidelines template: | - **File Naming:** {{file_naming_consistency}} - **Folder Organization:** {{folder_organization_approach}} - **Import/Export Patterns:** {{import_export_consistency}}
- id: infrastructure-deployment title: Infrastructure and Deployment Integration instruction: | Define how the enhancement will be deployed alongside existing infrastructure:
1. Use existing deployment pipeline and infrastructure 2. Identify any infrastructure changes needed 3. Plan deployment strategy to minimize risk 4. Define rollback procedures elicit: true sections: - id: existing-infrastructure title: Existing Infrastructure template: | **Current Deployment:** {{existing_deployment_summary}} **Infrastructure Tools:** {{existing_infrastructure_tools}} **Environments:** {{existing_environments}} - id: enhancement-deployment title: Enhancement Deployment Strategy template: | **Deployment Approach:** {{deployment_approach}} **Infrastructure Changes:** {{infrastructure_changes}} **Pipeline Integration:** {{pipeline_integration}} - id: rollback-strategy title: Rollback Strategy template: | **Rollback Method:** {{rollback_method}} **Risk Mitigation:** {{risk_mitigation}} **Monitoring:** {{monitoring_approach}}
- id: coding-standards title: Coding Standards and Conventions instruction: | Ensure new code follows existing project conventions:
1. Document existing coding standards from project analysis 2. Identify any enhancement-specific requirements 3. Ensure consistency with existing codebase patterns 4. Define standards for new code organization elicit: true sections: - id: existing-standards title: Existing Standards Compliance template: | **Code Style:** {{existing_code_style}} **Linting Rules:** {{existing_linting}} **Testing Patterns:** {{existing_test_patterns}} **Documentation Style:** {{existing_doc_style}} - id: enhancement-standards title: Enhancement-Specific Standards condition: New patterns needed for enhancement repeatable: true template: "- **{{standard_name}}:** {{standard_description}}" - id: integration-rules title: Critical Integration Rules template: | - **Existing API Compatibility:** {{api_compatibility_rule}} - **Database Integration:** {{db_integration_rule}} - **Error Handling:** {{error_handling_integration}} - **Logging Consistency:** {{logging_consistency}}
- id: testing-strategy title: Testing Strategy instruction: | Define testing approach for the enhancement:
1. Integrate with existing test suite 2. Ensure existing functionality remains intact 3. Plan for testing new features 4. Define integration testing approach elicit: true sections: - id: existing-test-integration title: Integration with Existing Tests template: | **Existing Test Framework:** {{existing_test_framework}} **Test Organization:** {{existing_test_organization}} **Coverage Requirements:** {{existing_coverage_requirements}} - id: new-testing title: New Testing Requirements sections: - id: unit-tests title: Unit Tests for New Components template: | - **Framework:** {{test_framework}} - **Location:** {{test_location}} - **Coverage Target:** {{coverage_target}} - **Integration with Existing:** {{test_integration}} - id: integration-tests title: Integration Tests template: | - **Scope:** {{integration_test_scope}} - **Existing System Verification:** {{existing_system_verification}} - **New Feature Testing:** {{new_feature_testing}} - id: regression-tests title: Regression Testing template: | - **Existing Feature Verification:** {{regression_test_approach}} - **Automated Regression Suite:** {{automated_regression}} - **Manual Testing Requirements:** {{manual_testing_requirements}}
- id: security-integration title: Security Integration instruction: | Ensure security consistency with existing system:
1. Follow existing security patterns and tools 2. Ensure new features don't introduce vulnerabilities 3. Maintain existing security posture 4. Define security testing for new components elicit: true sections: - id: existing-security title: Existing Security Measures template: | **Authentication:** {{existing_auth}} **Authorization:** {{existing_authz}} **Data Protection:** {{existing_data_protection}} **Security Tools:** {{existing_security_tools}} - id: enhancement-security title: Enhancement Security Requirements template: | **New Security Measures:** {{new_security_measures}} **Integration Points:** {{security_integration_points}} **Compliance Requirements:** {{compliance_requirements}} - id: security-testing title: Security Testing template: | **Existing Security Tests:** {{existing_security_tests}} **New Security Test Requirements:** {{new_security_tests}} **Penetration Testing:** {{pentest_requirements}}
- id: checklist-results title: Checklist Results Report instruction: Execute the architect-checklist and populate results here, focusing on brownfield-specific validation
- id: next-steps title: Next Steps instruction: | After completing the brownfield architecture:
1. Review integration points with existing system 2. Begin story implementation with Dev agent 3. Set up deployment pipeline integration 4. Plan rollback and monitoring procedures sections: - id: story-manager-handoff title: Story Manager Handoff instruction: | Create a brief prompt for Story Manager to work with this brownfield enhancement. Include: - Reference to this architecture document - Key integration requirements validated with user - Existing system constraints based on actual project analysis - First story to implement with clear integration checkpoints - Emphasis on maintaining existing system integrity throughout implementation - id: developer-handoff title: Developer Handoff instruction: | Create a brief prompt for developers starting implementation. Include: - Reference to this architecture and existing coding standards analyzed from actual project - Integration requirements with existing codebase validated with user - Key technical decisions based on real project constraints - Existing system compatibility requirements with specific verification steps - Clear sequencing of implementation to minimize risk to existing functionality

