# Content templates organized by incursion type SURGE_TEMPLATES = [ { "title": "🌊 Crimson Tide Surge", "description": "The shadows pulse with ancient energy, amplifying all training efforts. Strike while the darkness flows through you!", "effect": "All XP gains increased by 50% for the next 60 minutes", "target_exercise": "any", "target_reps": 0, # No specific target for surge events "reward_type": RewardType.XP, "reward_value": 50, # 50% XP boost "duration_hours": 1 }, { "title": "⚡ Lightning Reflexes Surge", "description": "Electric energy crackles through the realm. Your movements become swift and precise!", "effect": "All exercises grant +1 bonus rep for progression tracking", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 1, "duration_hours": 2 }, { "title": "🔥 Infernal Focus Surge", "description": "The fires of determination burn bright. Channel this intensity into your training!", "effect": "Next 3 completed quests grant double STR/END/TECH XP", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 2, "duration_hours": 4 } ]
CHALLENGE_TEMPLATES = [ { "title": "💀 Shadow Wraith Challenge", "description": "A spectral enemy emerges from the void. Prove your upper body dominance to banish it back to the shadows!", "target_exercise": "pull_ups", "target_reps": 100, "reward_type": RewardType.XP, "reward_value": 300, "duration_hours": 6 }, { "title": "🗡️ Blade Master's Trial", "description": "The ancient blade masters test your pushing power. Show them the strength of your resolve!", "target_exercise": "push_ups", "target_reps": 150, "reward_type": RewardType.XP, "reward_value": 250, "duration_hours": 8 }, { "title": "🏔️ Mountain's Endurance", "description": "The mountain spirits challenge your leg strength. Climb to new heights of power!", "target_exercise": "squats", "target_reps": 200, "reward_type": RewardType.XP, "reward_value": 275, "duration_hours": 12 }, { "title": "🌪️ Tempest Core Trial", "description": "Chaotic winds test your stability. Prove your core is unshakeable!", "target_exercise": "plank_seconds", "target_reps": 600, # 10 minutes total "reward_type": RewardType.XP, "reward_value": 200, "duration_hours": 6 } ]
