class FitnessIntegrations: """Handle integrations with Garmin Connect"""
@staticmethod async def sync_garmin_steps(user_id: int, access_token: str, access_token_secret: str) -> Optional[int]: """Sync steps from Garmin Connect IQ API""" try: yesterday = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
url = f"https://apis.garmin.com/wellness-api/rest/dailies" params = { "uploadStartTimeInSeconds": int((datetime.now() - timedelta(days=1)).timestamp()), "uploadEndTimeInSeconds": int(datetime.now().timestamp()) }
# Note: Garmin uses OAuth 1.0a, you'll need proper signing headers = { "Authorization": f"OAuth oauth_token=\"{access_token}\"" }
response = requests.get(url, params=params, headers=headers)
if response.status_code == 200: data = response.json() for daily in data: steps = daily.get("totalSteps", 0) if steps > 0: await FitnessIntegrations._log_steps_as_movement(user_id, steps) return steps
except Exception as e: print(f"Garmin sync error: {e}")
return None
@staticmethod async def _log_steps_as_movement(user_id: int, steps: int): """Convert steps to movement reps and log them""" # Convert steps to equivalent reps (e.g., 1000 steps = 100 "walking" reps) walking_reps = max(1, steps // 100) # At least 1 rep
# Log as walking movement from features.quests.logic.daily_quests.daily_quest_logic import update_quest_progress from features.quests.ui.weekly.weekly_contract_panel import update_weekly_progress from features.user.logic.xp_engine import add_xp, calculate_xp_for_movement from features.user.logic.user_data import load_user_data, save_user_data
# Update user stats data = await load_user_data(user_id) stats = data.setdefault("log_stats", {}) stats["walking"] = stats.get("walking", 0) + walking_reps
# Add XP only (no quest/contract progress) xp_earned = calculate_xp_for_movement("Walking", walking_reps) await add_xp(user_id, xp_earned) # If add_xp expects (user_id, xp_to_add), use: # await add_xp(user_id, xp_earned) # If it expects (xp_to_add, user_id), use: # await add_xp(xp_earned, user_id) # If signature is different, please adjust accordingly.
await save_user_data(user_id, data) print(f"Auto-synced {steps} steps as {walking_reps} walking reps for user {user_id}")
@staticmethod async def setup_fitness_sync(user_id: int, platform: str, credentials: Dict[str, str]): """Setup automatic fitness syncing for a user (Garmin only)""" if platform != "garmin": return False
data = await load_user_data(user_id) fitness_config = data.setdefault("fitness_integrations", {})
fitness_config[platform] = { "enabled": True, "credentials": credentials, "last_sync": None }
await save_user_data(user_id, data) return True from features.quests.logic.daily_quests.daily_quest_logic import update_quest_progress

""" Mock Awakening Service for development mode """ from datetime import date, datetime from typing import Dict, List, Any from api.models.awakening import ReadinessLevel
class MockAwakeningService: """Mock service for awakening system functionality in development mode"""
def __init__(self): # In-memory storage for mock data self._sessions = {} self._quests = {}
async def get_awakening_status(self, user_id: int, include_quests: bool = False) -> Dict: """Get mock awakening status""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
if session_key not in self._sessions: return { "status": "pending", "awakened": False, "quests_available": False, "readiness_level": None, "quests": [], "active_session": None, }
session = self._sessions[session_key] quests = []
if include_quests and session_key in self._quests: quests = self._quests[session_key]
return { "status": session["status"], "awakened": session["status"] != "pending", "quests_available": len(quests) > 0, "readiness_level": session["readiness_level"], "quest_count": session["quest_count"], "completed_quests": session.get("completed_quests", 0), "total_xp_gained": session.get("total_xp_gained", 0), "session_theme": "Shadow Training (Mock)", "quests": quests, "active_session": session, }
async def process_awakening(self, user_id: int, readiness_level: ReadinessLevel) -> Dict: """Process mock awakening""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Create mock session quest_count = self._get_quest_count_for_readiness(readiness_level)
self._sessions[session_key] = { "user_id": user_id, "awakening_date": today, "readiness_level": readiness_level.value, "status": "awakened", "quest_count": quest_count, "completed_quests": 0, "total_xp_gained": 0, "awakened_at": datetime.now().isoformat(), }
# Generate mock quests self._quests[session_key] = self._generate_mock_quests(quest_count, readiness_level)
return await self.get_awakening_status(user_id, include_quests=True)
async def complete_quest(self, user_id: int, quest_id: int) -> Dict: """Complete mock quest""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
if session_key in self._quests: for quest in self._quests[session_key]: if quest["id"] == quest_id: quest["status"] = "completed" quest["completed_at"] = datetime.now().isoformat()
# Update session progress if session_key in self._sessions: session = self._sessions[session_key] session["completed_quests"] += 1 session["total_xp_gained"] += quest["xp_reward"]
# Check if all quests completed completed_count = sum(1 for q in self._quests[session_key] if q["status"] == "completed") if completed_count >= session["quest_count"]: session["status"] = "completed" session["completed_at"] = datetime.now().isoformat() break
return await self.get_awakening_status(user_id, include_quests=True)
async def get_awakening_history(self, user_id: int, limit: int = 10) -> Dict: """Get mock awakening history""" # Return mock history data sessions = [] for i in range(min(3, limit)): # Mock 3 previous sessions past_date = date.today().replace(day=date.today().day - i - 1) sessions.append({ "awakening_date": past_date.isoformat(), "readiness_level": "standard", "status": "completed", "quest_count": 3, "completed_quests": 3, "total_xp_gained": 150, "awakened_at": f"{past_date}T08:00:00", "completed_at": f"{past_date}T20:00:00", })
return { "sessions": sessions, "total_sessions": len(sessions), }
async def recover_session(self, user_id: int) -> Dict: """Recover mock session""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Clear today's session if session_key in self._sessions: del self._sessions[session_key] if session_key in self._quests: del self._quests[session_key]
return await self.get_awakening_status(user_id)
def _get_quest_count_for_readiness(self, readiness_level: ReadinessLevel) -> int: """Determine quest count based on readiness level""" if readiness_level == ReadinessLevel.LOW: return 2 elif readiness_level == ReadinessLevel.STANDARD: return 3 else: # HIGH return 4
def _generate_mock_quests(self, quest_count: int, readiness_level: ReadinessLevel) -> List[Dict]: """Generate mock quests""" quests = [] quest_types = ["practice", "technique", "intensity"]
for i in range(quest_count): quest_type = quest_types[i % len(quest_types)] tier = (i % 3) + 1
quests.append({ "id": i + 1, "quest_data": { "title": f"Mock {quest_type.title()} Quest {i+1}", "description": f"Complete mock {quest_type} exercise", "type": quest_type, "difficulty": readiness_level.value, }, "tier": tier, "xp_reward": 50 * tier, "status": "available", "progress": {}, "completed_at": None, "created_at": datetime.now().isoformat(), })
return quests

""" Enhanced Awakening Panel UI - V2 Integrates with the new API-first architecture and backend services. """
import discord import asyncio import sentry_sdk import logging import httpx from typing import Union, Dict, Any, Optional, List from datetime import date
from shared.utils.ui_helpers import run_with_animation from shared.utils.headers import get_system_status_header from shared.utils.ui_styles import get_panel_sub_header from shared.utils.panel_registry import register from core.api_client import APIClient from shared.utils.error_helpers import handle_panel_errors
logger = logging.getLogger(__name__)
# --- UTILITY FUNCTIONS ---
def _map_tier_to_name(tier_value): """Map numeric tier values to tier names""" if isinstance(tier_value, int): tier_mapping = {1: "shadow", 2: "warrior", 3: "ascendant"} return tier_mapping.get(tier_value, "shadow") elif isinstance(tier_value, str): return tier_value.lower() return "shadow"
# --- FALLBACK AND ERROR EMBEDS ---
async def _create_fallback_embed(user: discord.User, error_type: str) -> discord.Embed: """Create a fallback embed for when the API is unavailable.""" header = get_system_status_header(user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening") content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;31m● System Alert: Service Unreachable\x1b[0m
" f"Status: \x1b[1;31m❌ OFFLINE\x1b[0m
" f"Reason: \x1b[1;33m{error_type}\x1b[0m

" f"\x1b[1;37mThe Awakening system is currently unable to
" f"connect to the central archives. Your data is
" f"safe, but services are temporarily unavailable.

" f"\x1b[1;37mPlease try again shortly.
" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.red()) embed.set_footer(text="Shadow Archive • System Alert") return embed
async def _build_quest_sync_pending_embed(header: str, sub_header: str) -> discord.Embed: """Build an embed for when quest data is still synchronizing.""" content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;33m● Awakening Data Synchronization\x1b[0m
" f"Status: \x1b[1;33m🔄 PENDING\x1b[0m

" f"\x1b[1;37mYour awakening session is active, but quest
" f"data is still being synchronized from the
" f"archives. This may take a few moments.

" f"\x1b[1;37mPlease wait for synchronization to complete.
" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.orange()) embed.set_footer(text="Shadow Archive • Data Synchronization") return embed
# --- MAIN AWAKENING PANEL ---
@register class EnhancedAwakeningPanel: key = "awakening" label = "Awakening" emoji = "🌅"
@staticmethod async def render_embed(bot, user: discord.User, **kwargs) -> discord.Embed: return await build_enhanced_awakening_embed(bot, user)
@staticmethod async def build_view(bot, user: discord.User, **kwargs) -> discord.ui.View: api_client = APIClient() try: status = await api_client.get_awakening_status(user) if status and status.get("awakened"): if status.get("status") == "active" and not status.get("quests"): return RecoveryView(bot, user) return EnhancedAwakeningMainView(bot, user) else: return EnhancedAwakeningInitialView(bot, user) except (httpx.RequestError, asyncio.TimeoutError): return await _create_fallback_view(bot, user)
async def build_enhanced_awakening_embed(bot, user: Union[discord.User, discord.Member]) -> discord.Embed: """Build the enhanced awakening panel embed with comprehensive error handling""" header = get_system_status_header(user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening")
try: api_client = APIClient() status = await asyncio.wait_for(api_client.get_awakening_status(user, include_quests=True), timeout=10.0)
if not status: status = {"awakened": False}
if status.get("awakened"): if status.get("status") == "active" and not status.get("quests"): return await _build_quest_sync_pending_embed(header, sub_header)
if status.get("status") == "completed": # Completed state xp_gained = status.get("total_xp_gained", 0) session_theme = status.get("session_theme", "Shadow Training") content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;32m● {session_theme} Complete\x1b[0m
" f"Status: \x1b[1;32m🏆 MASTERY ACHIEVED\x1b[0m

" f"\x1b[1;37mAll awakening quests completed. Total XP earned: \x1b[1;33m{xp_gained}\x1b[0m.
" f"Return at dawn for a new ritual.

" f"──────────────────────────
" f"```" ) color = discord.Color.green() else: # Awakened state completed = status.get("completed_quests", 0) total = status.get("quest_count", 0) xp_gained = status.get("total_xp_gained", 0) readiness = status.get("readiness_level", "unknown") session_theme = status.get("session_theme", "Shadow Training") progress_percent = (completed / total * 100) if total > 0 else 0 progress_bar = "█" * int(progress_percent / 10) + "░" * (10 - int(progress_percent / 10)) readiness_info = { "low": ("\x1b[1;34m", "🔋", "RECOVERY"), "standard": ("\x1b[1;33m", "⚖️", "BALANCED"), "high": ("\x1b[1;31m", "🔥", "PEAK") } color_code, emoji, level_text = readiness_info.get(readiness, ("\x1b[1;37m", "❓", "UNKNOWN")) content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;32m● {session_theme}\x1b[0m
" f"Readiness: {color_code}{emoji} {level_text}\x1b[0m

" f"\x1b[1;37m📊 Progress: [{progress_bar}] {progress_percent:.0f}%\x1b[0m
" f"Completed: \x1b[1;33m{completed}/{total}\x1b[0m | XP: \x1b[1;33m{xp_gained}\x1b[0m

" f"──────────────────────────
" f"```" ) color = discord.Color.orange() else: # Ready to awaken state content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Shadow Awakening Ritual\x1b[0m
" f"Status: \x1b[1;33mREADY TO BEGIN\x1b[0m

" f"\x1b[1;37mBegin your daily training ritual to unlock
" f"today's personalized quest selection.

" f"──────────────────────────
" f"```" ) color = discord.Color.blue()
embed = discord.Embed(description=content, color=color) embed.set_footer(text="Shadow Archive • Awakening V2")
except (asyncio.TimeoutError, httpx.RequestError) as e: logger.error(f"Awakening API call failed: {e}") sentry_sdk.capture_exception(e) return await _create_fallback_embed(user, "Service Unavailable") except Exception as e: logger.error(f"Error building awakening embed: {e}") sentry_sdk.capture_exception(e) return await _create_fallback_embed(user, "System Error")
return embed
