class EnhancedAwakeningInitialView(discord.ui.View): """View for when the user has not yet awakened.""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(EnhancedAwakeningButton())
class EnhancedAwakeningMainView(discord.ui.View): """Main view for an awakened user.""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(ViewQuestsButton()) self.add_item(ViewBriefingButton()) self.add_item(ViewHistoryButton())
