"""
API schemas for movement logging endpoints.

These schemas define the request and response models for the movement logging API,
including validation rules and documentation.
"""
from typing import Optional, Dict, Any, List
from pydantic import BaseModel, Field, field_validator, ConfigDict


class LogMovementRequest(BaseModel):
    """
    Request model for logging movement reps.

    This model validates the input for the POST /v2/events/log-movement endpoint.
    """

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "movement_id": 1,
                "reps": 10,
                "session_id": "workout_session_123"
            }
        }
    )

    movement_id: int = Field(
        ..., 
        gt=0, 
        description="ID of the movement being logged (must be positive)"
    )

    reps: int = Field(
        ..., 
        gt=0, 
        le=10000,  # Reasonable upper limit
        description="Number of repetitions performed (1-10000)"
    )

    session_id: Optional[str] = Field(
        None,
        max_length=100,
        description="Optional session tracking ID for analytics"
    )

    @field_validator('session_id')
    @classmethod
    def validate_session_id(cls, v):
        """Validate session_id format if provided."""
        if v is not None and len(v.strip()) == 0:
            return None
        return v


class MovementInfo(BaseModel):
    """Movement information in the response."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "id": 1,
                "name": "Push-ups"
            }
        }
    )

    id: int = Field(..., description="Movement ID")
    name: str = Field(..., description="Movement name")


class LevelUpInfo(BaseModel):
    """Information about a level-up that occurred."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "type": "strength",
                "new_level": 5,
                "points_earned": 2
            }
        }
    )

    type: str = Field(..., description="Type of level-up (global, strength, endurance, technique)")
    new_level: int = Field(..., description="New level achieved")
    points_earned: int = Field(..., description="Stat points earned from level-up")


class AuraUpdateInfo(BaseModel):
    """Information about aura changes."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "previous_aura": 1250,
                "new_aura": 1275,
                "change": 25,
                "reason": "Strength progression"
            }
        }
    )

    previous_aura: int = Field(..., description="Previous aura value")
    new_aura: int = Field(..., description="New aura value")
    change: int = Field(..., description="Aura change amount")
    reason: str = Field(..., description="Reason for aura change")


class LogMovementResponse(BaseModel):
    """
    Response model for successful movement logging.

    Contains all information about what happened during the movement log,
    including XP earned, level-ups, and aura changes.
    """

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "movement": {
                    "id": 1,
                    "name": "Push-ups"
                },
                "reps_logged": 10,
                "xp_earned": {
                    "global": 50,
                    "strength": 37
                },
                "level_ups": [
                    {
                        "type": "strength",
                        "new_level": 5,
                        "points_earned": 2
                    }
                ],
                "aura_update": {
                    "previous_aura": 1250,
                    "new_aura": 1275,
                    "change": 25,
                    "reason": "Strength progression"
                },
                "session_id": "workout_session_123"
            }
        }
    )

    movement: MovementInfo = Field(..., description="Information about the logged movement")

    reps_logged: int = Field(..., description="Number of reps that were logged")

    xp_earned: Dict[str, int] = Field(
        ..., 
        description="XP earned by category (global, strength, endurance, technique)"
    )

    level_ups: List[LevelUpInfo] = Field(
        default_factory=list,
        description="List of level-ups that occurred"
    )

    aura_update: Optional[AuraUpdateInfo] = Field(
        None,
        description="Aura update information if aura changed"
    )

    session_id: Optional[str] = Field(
        None,
        description="Session ID if provided in request"
    )


class ErrorResponse(BaseModel):
    """Standard error response model."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "error": "Movement not found",
                "detail": "Movement with ID 999 does not exist"
            }
        }
    )

    error: str = Field(..., description="Error message")
    detail: Optional[str] = Field(None, description="Additional error details")

""" Pydantic schemas for DungeonKey and DungeonProgress models for V2. These are simple data containers aligned with our SQLAlchemy models. """ from pydantic import BaseModel, Field, ConfigDict from typing import Optional
# DungeonKey Schemas class DungeonKeyBase(BaseModel): """Base schema for DungeonKey with common fields""" ascendant_id: int = Field(..., description="The user who owns these keys") key_type: str = Field(default="shadow_key", max_length=50, description="The type of key") quantity: int = Field(default=0, ge=0, description="How many keys of this type the user has")
class DungeonKeyCreate(DungeonKeyBase): """Schema for creating a new DungeonKey""" pass
class DungeonKeyUpdate(BaseModel): """Schema for updating a DungeonKey""" key_type: Optional[str] = Field(None, max_length=50, description="The type of key") quantity: Optional[int] = Field(None, ge=0, description="How many keys of this type the user has")
class DungeonKeyResponse(DungeonKeyBase): """Schema for DungeonKey responses""" id: int = Field(..., description="Unique identifier for the dungeon key record")
model_config = ConfigDict(from_attributes=True)
# DungeonProgress Schemas class DungeonProgressBase(BaseModel): """Base schema for DungeonProgress with common fields""" ascendant_id: int = Field(..., description="The user whose progress is being tracked") highest_level_completed: int = Field(default=0, ge=0, description="The highest dungeon level completed")
class DungeonProgressCreate(DungeonProgressBase): """Schema for creating a new DungeonProgress""" pass
class DungeonProgressUpdate(BaseModel): """Schema for updating DungeonProgress""" highest_level_completed: Optional[int] = Field(None, ge=0, description="The highest dungeon level completed")
class DungeonProgressResponse(DungeonProgressBase): """Schema for DungeonProgress responses""" id: int = Field(..., description="Unique identifier for the dungeon progress record")
model_config = ConfigDict(from_attributes=True)

""" Generate Daily Quests - Quest generation logic for daily quests """
import random from datetime import datetime from features.user.logic.xp_engine import MOVEMENT_DATA
def pick_main_buff(): import random buffs = ["xp_boost_5", "recovery_aura", "shadow_focus", None] return random.choice(buffs)
def pick_side_buff(): import random side_buffs = ["bonus_log_chance", "focus_hint", None, None] return random.choice(side_buffs)
QUEST_NAMES = { 1: "Veins of the Abyss", 2: "Ritual of the Core", 3: "Iron Cradle", 4: "Whispers of the Flesh", 5: "Burden of Bone", 6: "Elegy of Sinew", 7: "Grim Edict", 8: "Oath to Obsidian", 9: "Feast of the Hollow", 10: "The Nameless Reign", }
QUEST_QUOTES = { 1: "The path begins in silence.", 2: "Steel your breath for the shaping.", 3: "Pain teaches what memory forgets.", 4: "Your flesh remembers. Make it earn the silence.", 5: "The marrow bends before it breaks.", 6: "Scars do not speak. They judge.", 7: "You are your burden. Carry it.", 8: "The forge sings for no one.", 9: "Ritual is strength made obedient.", 10: "What rises from the grave no longer fears the dark.", }
def get_unlocked_tiers(level: int): return list(range(1, min(11, (level - 1) // 5 + 2))) # +1 tier every 5 levels
def get_daily_quest_count(level: int) -> int: return min(3 + (level // 10), 7)
def get_movements_by_tier(tiers: list[int]): return [m for m, info in MOVEMENT_DATA.items() if info["tier"] in tiers]
def reps_for_tier(tier: int): return 20 + (tier - 1) * 10 # Tier 1: 20 → Tier 10: 110
def roll_buff(tier: int): if random.random() < 0.3: buff_value = 5 + (tier // 3) * 5 # Tier 3+ = +10%, Tier 6+ = +15% return f"+{buff_value}% XP for 24h" return None
def calculate_xp_reward(movements: dict): total = 0 for move, reps in movements.items(): xp_per_rep = MOVEMENT_DATA.get(move, {}).get("xp", 1) total += reps * xp_per_rep return int(total)
async def generate_daily_quests(user_id: int, level: int, bot=None): """Generate daily quests for a user""" tiers = get_unlocked_tiers(level) quest_count = get_daily_quest_count(level) all_quests = []
for i in range(quest_count): tier = random.choice(tiers) reps = reps_for_tier(tier)
pool = get_movements_by_tier([t for t in tiers if t <= tier])
# Fix: Handle cases where pool has fewer movements than needed movement_count = min(4, len(pool)) # Use available movements, max 4 if movement_count == 0: # Fallback: use all available movements regardless of tier pool = list(MOVEMENT_DATA.keys()) movement_count = min(4, len(pool))
chosen = random.sample(pool, k=movement_count)
targets = {m: reps for m in chosen} progress = {m: 0 for m in chosen}
quest = { "id": f"daily_{user_id}_{datetime.utcnow().strftime('%Y%m%d')}_{i}", # Add unique ID "tier": tier, "Tier": tier, # Keep uppercase for legacy compatibility "QuestName": QUEST_NAMES.get(tier, f"Tier {tier} Quest"), "Flavor": QUEST_QUOTES.get(tier, ""), "movements": chosen, "Movements": chosen, # Keep uppercase for legacy compatibility "targets": targets, "Targets": targets, # Keep uppercase for legacy compatibility "target": {"sets": 1, "reps": reps}, # New format for awakening system "progress": {m: {"sets": 0, "reps": 0} for m in chosen}, # New format "Progress": progress, # Legacy format "BuffReward": roll_buff(tier), "xp_reward": calculate_xp_reward(targets), "XPReward": calculate_xp_reward(targets), # Legacy compatibility "active": False, "Active": False, "completed": False, "Completed": False, "_completed_flag": False, "_new_format": True }
all_quests.append(quest)
return all_quests

