logger = logging.getLogger(__name__)
router = APIRouter(prefix="/api/v2/awakening", tags=["awakening"])
@router.post("/action", response_model=AwakeningActionResponse) async def create_awakening_session( request: AwakeningActionRequest, current_user: dict = Depends(get_current_user), db = Depends(get_db) ) -> AwakeningActionResponse: """ Create or retrieve today's awakening session for the user.
Args: request: Contains user_id and readiness_level current_user: Authenticated user information db: Database session
Returns: AwakeningActionResponse with session data and quests
Raises: HTTPException: If user not found or invalid readiness level """ try: awakening_service = AwakeningService(db)
