return AwakeningActionResponse(**session_data)
except ValueError as e: logger.error(f"Validation error in create_awakening_session: {e}") raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail=str(e) ) except Exception as e: logger.error(f"Error creating awakening session: {e}") raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Failed to create awakening session" )
